	"fmt"
	"io"
	"strings"
	"testing"
)

func topKStr(t *testing.T, s string, k int, stop []string) []WordCount {
	t.Helper()
	res, err := TopK(strings.NewReader(s), k, stop)
	if err != nil {
		t.Fatalf("TopK: %v", err)
	}
	return res
}

func strRes(res []WordCount) []string {
	out := make([]string, len(res))
	for i, rc := range res {
		out[i] = fmt.Sprintf("%s:%d", rc.Word, rc.Count)
	}
	return out
}

func eq(t *testing.T, got, want []string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("got %v want %v", got, want)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Fatalf("got %v want %v", got, want)
		}
	}
}

func TestBasics(t *testing.T) {
	// don't, o'clock, case-folding, stops, punctuation separators
	got := strRes(topKStr(t, "Don't stop! don't stop o'clock O'CLOCK it's a a a the", 10, nil))
	want := []string{"a:3", "don't:2", "it's:1", "o'clock:2", "stop:2", "the:1"}
	// sort by count desc, then word asc: a:3; don't:2,o'clock:2,stop:2 (tie order: don't,o'clock,stop); it's:1,the:1
	want = []string{"a:3", "don't:2", "o'clock:2", "stop:2", "it's:1", "the:1"}
	eq(t, got, want)
}

func TestStops(t *testing.T) {
	res := topKStr(t, "the THE The the a", 10, []string{"the", "A"})
	eq(t, strRes(res), []string{"a:1"})
}

func TestKSmall(t *testing.T) {
	res := topKStr(t, "a a b b c c c", 2, nil)
	eq(t, strRes(res), []string{"c:3", "a:2"})

	// k=0 -> empty non-nil
	res, err := TopK(strings.NewReader("a a a"), 0, nil)
	if err != nil || res == nil || len(res) != 0 {
		t.Fatalf("k=0: res=%v err=%v", res, err)
	}
	// negative k
	res, err = TopK(strings.NewReader("a a a"), -3, nil)
	if err != nil || res == nil || len(res) != 0 {
		t.Fatalf("k<0: res=%v err=%v", res, err)
	}
	// empty input
	res, err = TopK(strings.NewReader(""), 5, nil)
	if err != nil || res == nil || len(res) != 0 {
		t.Fatalf("empty: res=%v err=%v", res, err)
	}
}

func TestApostropheRules(t *testing.T) {
	got := strRes(topKStr(t, "it's 'it' it'' 5't 5'th don't5 x'x", 10, nil))
	// it's:1 ; 'it' -> it:1 ; it'' -> it:2 ; 5't -> 5:1 t:1 ; 5'th -> 5:1, t:1 => 5:2, t:2
	// don't5:1 ; x'x:1
	want := []string{"it:2", "t:2", "5:2", "don't5:1", "it's:1", "x'x:1"}
	eq(t, got, want)
}

func TestUnicodeAndDigits(t *testing.T) {
	// unicode letters, digits, mixed runs; tolower on unicode
	got := strRes(topKStr(t, "café Café 42 42 naïve naïve's", 10, nil))
	want := []string{"café:2", "42:2", "naïve:1", "naïve's:1"}
	// tie: 42 and café both 2 -> byte order: "42" < "café"
	eq(t, got, want)
}

type errReader struct {
	io.Reader
	n   int
	err error
}

func (e *errReader) Read(p []byte) (int, error) {
	e.n++
	if e.n == 2 {
		return 0, errors.New("boom")
	}
	return e.Reader.Read(p)
}

func TestReadError(t *testing.T) {
	r := errReader{Reader: strings.NewReader("hello hello hello"), err: errors.New("boom")}
	_, err := TopK(&r, 3, nil)
	if err == nil || err.Error() != "boom" {
		t.Fatalf("err = %v, want boom", err)
	}
}

// very long line, large input, rune split across buffer boundaries
func TestLargeAndBoundary(t *testing.T) {
	const chunk = 1024 * 1024
	// single "line" of 5MB of "word " + a 4-byte emoji crossing boundaries
	var b strings.Builder
	for i := 0; i < chunk*5; i += 5 {
		b.WriteString("word")
	}
	// emoji U+1F600 = 4 bytes f0 9f 98 80; sprinkle a few, at known offsets
	b.WriteRune('\U0001F600')
	b.WriteString("word word Don't")
	b.WriteRune('\U0001F600')
	b.WriteString(" don't")

	res, err := TopK(strings.NewReader(b.String()), 10, nil)
	if err != nil {
		t.Fatal(err)
	}
	eq(t, strRes(res), []string{"word:1048576", "don't:2"})
}

func TestStopWithLower(t *testing.T) {
	// stop entry case-insensitive both directions
	res := topKStr(t, "Apple apple APPLE", 10, []string{"APPLE"})
	if len(res) != 0 {
		t.Fatalf("got %v, want none", res)
	}
}
