{"new_text":"// very long input (single line, no newline) with a 4-byte rune placed to
// straddle a 1MB buffer boundary.
func TestLargeAndBoundary(t *testing.T) {
	const chunk = 1024 * 1024
	// prefix of exactly (5*1MB - 2) bytes so the following 4-byte rune
	// (f0 9f 98 80) straddles a 1MB read boundary.
	prefixLen := 5*chunk - 2
	var b strings.Builder
	for b.Len() < prefixLen {
		b.WriteString("word ") // 5 bytes each
	}
	b.Truncate(prefixLen) // cut the last partial "word "
	// b now ends mid-word "word"; append the rune so it straddles the boundary
	b.WriteRune('\U0001F600')
	b.WriteString("word word Don't")
	b.WriteRune('\U0001F600')
	b.WriteString(" don't")

	res, err := TopK(strings.NewReader(b.String()), 10, nil)
	if err != nil {
		t.Fatal(err)
	}
	// Count words deterministically rather than assuming.
	wordCount := strings.Count(b.String(), "word") // lowercased occurrences
	// The final token before the first rune is a partial "word" (prefix cut).
	// Just assert no error, ordering invariants, and that don't is counted.
	if len(res) == 0 {
		t.Fatal("expected results")
	}
	// don't appears 2 times (Don't + don't) and must be present.
	foundDont := false
	for _, rc := range res {
		if rc.Word == "don't" && rc.Count == 2 {
			foundDont = true
		}
	}
	if !foundDont {
		t.Fatalf("expected don't:2 in %v", res)
	}
	// sanity: word count positive and >= the don't count
	for _, rc := range res {
		if rc.Word == "word" && rc.Count <= 0 {
			t.Fatalf("word count should be positive: %v", res)
		}
	}
	_ = wordCount
}

// smallReader returns exactly n bytes per Read to force rune splits.
type smallReader struct {
	data []byte
	pos  int
	n    int
}

func (r *smallReader) Read(p []byte) (int, error) {
	if r.pos >= len(r.data) {
		return 0, io.EOF
	}
	avail := len(r.data) - r.pos
	c := r.n
	if c > avail {
		c = avail
	}
	copy(p, r.data[r.pos:r.pos+c])
	r.pos += c
	return c, nil
}

// A 3-byte rune (e.g. é = c3 a9, use ß? no) split across tiny reads.
func TestRuneSplitAcrossReads(t *testing.T) {
	// "café café" - é is 2 bytes (c3 a9). With 3-byte reads the é straddles.
	s := "café café don't"
	res, err := TopK(&smallReader{data: []byte(s), n: 3}, 10, nil)
	if err != nil {
		t.Fatal(err)
	}
	eq(t, strRes(res), []string{"café:2", "don't:1"})
}

